module logic_function (A, B, Ci, S, Co);
  input A, B, Ci;
  output S, Co;
  wire   n10, n11, n12;

  // XNOR2_X1 U1 ( .A(Ci), .B(n12), .ZN(S) );
  assign n12 = ~(A ^ B);
  assign S = ~(n12 ^ Ci);

