    reg CLK;
    reg EN;
    reg RESET;
    reg TE;
    wire ENCLK;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    ClockGating dut (
        .CLK(CLK),
        .EN(EN),
        .RESET(RESET),
        .TE(TE),
        .ENCLK(ENCLK)
    );

    // Clock generation (10ns period)
    initial begin
        CLK = 0;
        forever #5 CLK = ~CLK;
    end

        task reset_dut;

        begin
            EN = 0;
            RESET = 0;
            TE = 0;
            #10;
        end
        endtask
    task testcase001;

        begin
            $display("\nRunning testcase001: EN=0 (Clock Gated Off)");
            reset_dut();
            @(negedge CLK);
            EN = 0;
            RESET = 0;
            TE = 0;


            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b0);


            @(negedge CLK);
            #2;
            #1;

            check_outputs(1'b0);
        end
        endtask

    task testcase002;

        begin
            $display("\nRunning testcase002: EN=1, RESET=0 (Transparent Clock)");
            reset_dut();
            @(negedge CLK);
            EN = 1;
            RESET = 0;
            TE = 0;


            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b1);


            @(negedge CLK);
            #2;
            #1;

            check_outputs(1'b0);
        end
        endtask

    task testcase003;

        begin
            $display("\nRunning testcase003: EN=1, RESET=1, TE=0 (Clock Gated Off via Reset)");
            reset_dut();
            @(negedge CLK);
            EN = 1;
            RESET = 1;
            TE = 0;


            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b0);


            @(negedge CLK);
            #2;
            #1;

            check_outputs(1'b0);
        end
        endtask

    task testcase004;

        begin
            $display("\nRunning testcase004: EN=1, RESET=1, TE=1 (Inverted Clock)");
            reset_dut();
            @(negedge CLK);
            EN = 1;
            RESET = 1;
            TE = 1;


            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b0);


            @(negedge CLK);
            #2;
            #1;

            check_outputs(1'b1);
        end
        endtask

    task testcase005;

        begin
            $display("\nRunning testcase005: Transition Normal to Inverted");
            reset_dut();
            @(negedge CLK);
            EN = 1;
            RESET = 0;
            #10;

            @(negedge CLK);
            RESET = 1;
            TE = 1;

            @(posedge CLK);
            #2;
            #1;

            check_outputs(1'b0);

            @(negedge CLK);
            #2;
            #1;

            check_outputs(1'b1);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("ClockGating Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input expected_ENCLK;
        begin
            if (expected_ENCLK === (expected_ENCLK ^ ENCLK ^ expected_ENCLK)) begin
                $display("PASS");
