module gray_counter(
  input                clk,
  input                rst_n,
  output reg  [15:0]   Q
);

  reg [15:0] next_state;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      Q <= 16'b0;
      next_state <= 16'b0;
    end
    else begin
      Q <= next_state;
      next_state <= Q ^ ({Q[14:0],1'b0});
    end
  end

endmodule

